SourceCode.Declaration:
/// <summary>
/// getMenu's answer: RootMenuId is the worker's Home menu ('' when none is set up - the app
/// then keeps its plain list), Menus every menu reachable from it.
/// </summary>
[DataContractAttribute]
class HSMobileOpsMenuResponse
{
    boolean  success;
    str      errorCode;
    str      rootMenuId;
    List     menus;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('RootMenuId')]
public str parmRootMenuId(str _value = rootMenuId)
{
    rootMenuId = _value;
    return rootMenuId;
}

[DataMemberAttribute('Menus'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsMenuRow))]
public List parmMenus(List _value = menus)
{
    menus = _value;
    return menus;
}
